CHS = []

CHS.append(CH("What Vectiq is and where it fits",
 ("Vectiq", ["Vectiq | is | Community bot", "Vectiq | runs on | Vector", "Vectiq | built on | vector-sdk-py", "Vectiq | stores data in | SQLite", "Vectiq | splits into | Modules", "Modules | grouped as | Safety", "Modules | grouped as | Members", "Modules | grouped as | Community", "Modules | grouped as | Fun", "Modules | grouped as | Integrations"]),
 ["Vectiq is a community-management bot for Vector, the private messenger. It does what Discord bots such as MEE6 do for a server: moderation, levels, a coin economy, tickets, events, giveaways and games.",
  "It is written in Python from scratch on top of vector-sdk-py, uses SQLite instead of a separate database server, and is MIT licensed by lucky-edgelord and the Vectiq contributors. This course walks through how it is built so you can run it, read it and extend it.",
  "The big idea to remember: every feature is a module with its own cog (the Vector side), store (the database side) and settings. You switch modules on and off, and the rest stays out of the way."],
 [("Vector", "A private messenger with communities, channels and roles, similar in shape to Discord."), ("Community bot", "A program with its own account that joins communities and helps run them."), ("Module", "One switchable feature, such as leveling or tickets."), ("Cog", "A class of commands and listeners; it holds all the Vector input and output of a feature."), ("SQLite", "A database that lives in one file; no server to install.")],
 ["Vectiq 0.1.0, MIT, Python 3.10 or newer.", "Core dependencies: vector-sdk-py, PyYAML and Pillow.", "Optional extras: webhooks, dashboard, music, mcp, nudenet, nsfw-detector.", "Five module groups: Safety, Members, Community, Fun, Integrations.", "About 15,900 lines of Python and 25 documentation pages."],
 [T("Picture a busy group chat with hundreds of people. Someone has to greet newcomers, remove spam, hand out roles, run giveaways and keep the peace. A community bot does these jobs automatically, so humans can just talk."),
  F("1-1", "Vectiq is the Python layer between your community and the Vector network."),
  T("Vectiq stands on vector-sdk-py, a Python library with a discord.py style API that wraps the official Rust Vector SDK. That means commands are written with familiar decorators, and the hard parts, encryption and relays, are done underneath."),
  T("Vectiq itself is organised in modules. The built-in ones are moderation, link safety, image guard, Sentire (automod), verification, security cam, welcome, onboarding, roles, tickets, events, notifications, utility, leveling, economy, giveaways, music, games, webhooks, MCP and the dashboard."),
  F("1-2", "Modules are grouped by purpose; two core cogs are always loaded."),
  TB("Optional extras", ["Extra", "Adds"], [["webhooks", "send events to other tools"], ["dashboard", "FastAPI web admin (fastapi, uvicorn)"], ["music", "yt-dlp for audio"], ["mcp", "FastMCP so AI assistants can manage the community"], ["nudenet / nsfw-detector", "local picture detectors"]]),
  TB("What each group is for", ["Group", "Examples", "Purpose"], [["Safety", "moderation, link safety, image guard", "keep the place clean"], ["Members", "verification, onboarding, roles", "welcome and sort people"], ["Community", "tickets, events, giveaways", "run activities"], ["Fun", "leveling, economy, games, music", "give people reasons to stay"], ["Integrations", "webhooks, MCP, dashboard", "connect to the outside"]]),
  T("The project is licensed under MIT, so you may use and change it freely if you keep the licence notice. Several ideas are credited in its own docs: Logiq and MEE6 for the feature shape, GateBot by henk.tech for verification ideas, and Sentire by JSKitty of VectorPrivacy for automod.")],
 [("What does Vectiq do?", ["Manages Vector communities", "Encrypts messages", "Replaces Vector", "Hosts websites"], 0, "It is a community bot."), ("Which library does it build on?", ["vector-sdk-py", "discord.py only", "Django", "Flask"], 0, "A discord.py style Vector library."), ("Where does Vectiq keep its data?", ["A SQLite file", "MongoDB", "Cloud only", "Plain text"], 0, "No database server needed."), ("What is a module?", ["A switchable feature", "A theme", "A database", "A user"], 0, "Each feature can be on or off."), ("Which licence?", ["MIT", "GPL only", "Proprietary", "None"], 0, "Free to use with the notice.")],
 [("What is Vectiq?", "A community-management bot for Vector, built in Python on vector-sdk-py."), ("Name the five module groups.", "Safety, Members, Community, Fun, Integrations."), ("Why SQLite?", "One file, no server to run."), ("What is a cog?", "The Vector-facing part of a feature: commands and listeners.")],
 [MATCH("Match group to module", "Pair each module with its group.", [("moderation", "Safety"), ("verification", "Members"), ("tickets", "Community"), ("economy", "Fun"), ("webhooks", "Integrations")]),
  FILL("The big picture", "Vectiq is a {{community}} bot that runs on {{Vector}}, uses {{SQLite}} for storage and splits features into {{modules}}.")]))

CHS.append(CH("Project layout and the layering rule",
 ("Layers", ["Cogs | do | Vector I/O", "Stores | do | All SQL", "db | provides | SQLite facade", "games | hold | Pure rules", "render | draws | Pillow images", "Cogs | call | Stores", "Stores | call | db", "Rules | never touch | Network"]),
 ["Vectiq keeps different jobs in different folders. Cogs talk to Vector. Stores talk to the database. Game rules and drawing code do neither. This one rule is the reason almost everything can be tested without a live bot.",
  "When you read the code, start in src/vectiq/. Ask which job a file does, and you know which folder it lives in. When you add a feature, you write one file in each layer.",
  "The rule is simple to state: SQL appears only in stores, Vector calls appear only in cogs, and rules never touch the network."],
 [("Layering", "Splitting code so each part has one job and only calls the layer below."), ("Store", "A small class holding every SQL query for one feature."), ("Pure function", "Output depends only on input; no network, files or clock unless passed in."), ("Facade", "A simple front for something more complex, such as SQLite behind async calls."), ("Package", "A folder of Python code you can install; here, vectiq.")],
 ["cogs/ = Vector input and output.", "stores/ = all SQL.", "db/ = connection and migrations.", "games/ and render/ = pure rules and pictures.", "A cog never writes a query; it calls a store."],
 [T("Imagine a restaurant. The waiter talks to customers, the cook handles food, and the pantry holds ingredients. If the waiter started cooking, nothing could be tested or swapped. Vectiq splits its code the same way."),
  F("2-1", "Each layer calls only the one below it."),
  T("The folders you will meet: app.py builds the bot, config.py loads settings, modules.py describes modules, plugin.py is the stable plugin API, and the folders cogs, stores, db, games, render, dashboard and utils hold the features."),
  TB("Folders and jobs", ["Folder", "Job"], [["cogs/", "commands, listeners and loops; all Vector I/O"], ["stores/", "SQL for one feature each"], ["db/", "SQLite connection and migrations"], ["games/", "rules in pure Python plus WebXDC front ends"], ["render/", "Pillow pictures such as rank cards"], ["dashboard/", "FastAPI server and web page"], ["utils/", "durations, time parsing, embeds, checks"]]),
  T("Follow one message through the code. A member sends a message, the leveling cog hears it, asks the level store how much XP to give, the store writes in a database transaction, and the cog replies with a rank picture drawn by the render layer."),
  F("2-2", "Vector appears only at the two ends of the journey."),
  TB("Who may touch what", ["Layer", "May use", "Must not use"], [["cogs", "Vector, stores, render", "raw SQL"], ["stores", "the database", "Vector"], ["games rules", "plain Python", "network, Vector"], ["render", "Pillow", "database, network"]]),
  T("The payoff is testing. A store can be tested against an in-memory database, a rule can be tested with plain values, and only the thin cog needs a fake Vector. You will see this again in the last chapter.")],
 [("Where does SQL live?", ["Only in stores", "In cogs", "In rules", "In render"], 0, "Cogs call stores."), ("Which layer talks to Vector?", ["Cogs", "Stores", "db", "render"], 0, "All Vector I/O is in cogs."), ("Do game rules use the network?", ["No", "Yes", "Sometimes", "Always"], 0, "They are pure Python."), ("Why this layering?", ["Easy testing", "Faster Python", "Smaller zip", "Looks nice"], 0, "Almost everything runs without a live bot."), ("Which folder draws rank cards?", ["render", "stores", "db", "utils"], 0, "Pillow lives there.")],
 [("State the layering rule.", "SQL only in stores, Vector calls only in cogs, rules never touch the network."), ("What is plugin.py?", "The stable API plugins may import."), ("Where is the config loaded?", "config.py."), ("What does a cog call to save data?", "A store method.")],
 [MATCH("Match folder to job", "Pair each folder with its job.", [("cogs", "Vector input and output"), ("stores", "SQL queries"), ("db", "connection and migrations"), ("render", "Pillow pictures"), ("games", "pure rules")]),
  FILL("The rule", "{{Cogs}} talk to Vector, {{stores}} talk to the database, and {{rules}} touch neither.")]))

CHS.append(CH("The database: async SQLite, transactions and migrations",
 ("Database", ["Database | wraps | sqlite3", "Database | uses | One connection", "Database | uses | asyncio Lock", "Calls | run in | to_thread", "Database | offers | Transactions", "Database | runs | Migrations", "Migrations | tracked by | user_version", "Snapshot | uses | Online backup"]),
 ["SQLite is a database in one file. Python's sqlite3 module is blocking, so a naive bot would freeze whenever the database was busy. Vectiq wraps it in an async Database class: one shared connection, every call run in a worker thread, and a lock so calls take turns.",
  "Transactions group several changes into one all-or-nothing step. The Database offers transaction(), which starts with BEGIN IMMEDIATE and rolls back if your code raises an error.",
  "Migrations are numbered SQL scripts. The database remembers how many it has run in PRAGMA user_version, so an old file upgrades itself at start-up. The golden rule: never edit a migration that has shipped, append a new one."],
 [("Transaction", "A group of statements that all succeed or all fail."), ("WAL", "Write-ahead logging: readers and a writer can work at the same time."), ("Migration", "A numbered SQL script that moves the schema one step forward."), ("user_version", "A number stored inside the SQLite file; Vectiq uses it as the schema version."), ("to_thread", "Run blocking code in a worker thread so the event loop stays free.")],
 ["One connection, one lock, every call in asyncio.to_thread.", "Pragmas: WAL, foreign_keys ON, synchronous NORMAL, busy_timeout 5000.", "transaction() uses BEGIN IMMEDIATE and rolls back on an exception.", "Migrations apply in order, those newer than user_version.", "snapshot() copies safely; restore_from() checks integrity and refuses newer versions."],
 [T("A bank teller who is interrupted halfway through a transfer might take money out and never put it in. A transaction is the rule that says: finish the whole job, or undo all of it."),
  F("3-1", "Every call queues behind a lock and runs in a thread, so the bot never freezes."),
  C("async with db.transaction() as tx:\n    await tx.execute(\"UPDATE accounts SET coins = coins - ? WHERE id = ?\", (50, a))\n    await tx.execute(\"UPDATE accounts SET coins = coins + ? WHERE id = ?\", (50, b))\n# illustration: leaving the block commits; an exception rolls both back", "python"),
  TB("Database settings", ["Pragma", "Value", "Why"], [["journal_mode", "WAL", "readers do not block the writer"], ["foreign_keys", "ON", "links between tables are enforced"], ["synchronous", "NORMAL", "fast and safe enough with WAL"], ["busy_timeout", "5000 ms", "wait rather than fail when busy"], ["isolation_level", "None", "Vectiq controls transactions itself"]]),
  T("All identifiers in the tables are TEXT: user and community ids are long strings, not numbers. Tables you will meet include guild_settings, mod_cases, levels, wallets, shop_items, inventory, transactions, tickets and verified_members. Wallets have a CHECK that balance and bank are never negative."),
  TB("Database methods", ["Method", "Does"], [["execute / insert", "run one statement, return rows changed or the new id"], ["one / all / scalar", "read one row, all rows, or a single value"], ["executemany", "run a statement for many rows"], ["transaction()", "all-or-nothing block"], ["migrate()", "apply newer migrations"], ["snapshot(dest)", "online backup to a file"], ["restore_from(src)", "check integrity, refuse newer, migrate"]]),
  F("3-2", "Start-up compares the stored version with the migration list and applies only what is newer."),
  T("A restore point from a newer Vectiq cannot be loaded by an older one, because its user_version is higher than the list the old code knows. The database refuses rather than guess.")],
 [("Why run sqlite3 calls in a thread?", ["The library blocks", "It is faster", "It is required by SQL", "To save disk"], 0, "Blocking calls would freeze the bot."), ("What does a transaction guarantee?", ["All or nothing", "Speed", "Encryption", "Caching"], 0, "Atomic changes."), ("Where is the schema version stored?", ["PRAGMA user_version", "config.yaml", "A text file", "The dashboard"], 0, "Inside the SQLite file."), ("How should you change a shipped table?", ["Append a new migration", "Edit the old one", "Delete the file", "Use the dashboard"], 0, "Never edit an applied migration."), ("What happens on a rolled-back error?", ["No change is kept", "Half is kept", "The file is deleted", "Nothing runs"], 0, "Both writes undone.")],
 [("Why one connection and a lock?", "SQLite handles one writer; the lock keeps async calls orderly."), ("What does BEGIN IMMEDIATE do?", "Takes the write lock at the start so the transaction cannot be surprised."), ("What is WAL?", "A journal mode where readers and a writer work together."), ("What is a migration?", "A numbered SQL script that upgrades the schema one step.")],
 [MATCH("Match term to meaning", "Pair each database term with what it means.", [("migration", "numbered schema upgrade"), ("transaction", "all or nothing"), ("WAL", "readers and writer coexist"), ("to_thread", "keep the loop free"), ("user_version", "schema number in the file")]),
  FILL("Safe storage", "Calls run in a {{thread}}, grouped changes use a {{transaction}}, and the schema is upgraded by {{migrations}}."),
  PL("Which migrations run?", "Write pending(version, total). version is the number already applied and total is how many scripts exist. Return the list of script numbers to run, in order, starting at version + 1. If version is larger than total, return None because the file is newer than the code.", "pending(version, total)", '''
def pending(version, total):
    if version > total:
        return None
    return list(range(version + 1, total + 1))
''', [[0, 3], [3, 8], [8, 8], [9, 8], [2, 3]], "Compare first, then list the numbers from version + 1 up to total.")]))

CHS.append(CH("Configuration: defaults, YAML, dashboard overrides and secrets",
 ("Config", ["Config | starts with | DEFAULTS", "config.yaml | merges over | DEFAULTS", "Dashboard | overrides | config.yaml", "Overrides | live in | Database", "Secrets | live in | .env", "Merge | is | Recursive", "Wizard | writes | config.yaml", "CLI | can | Export and import"]),
 ["Vectiq has hundreds of settings, one section per module. They come from layers. First, the DEFAULTS built into config.py, so every setting has a safe value. Second, your config.yaml, merged on top. Third, dashboard changes, kept in the database.",
  "Merging is recursive. If your file only changes the daily amount, the other economy settings keep their defaults.",
  "Secrets such as the bot's key never go in config.yaml. They live in .env.",
  "The command-line tool helps: --check validates, --init makes a starter config, --setup runs a wizard, and --export-config and --import-config move settings between machines."],
 [("DEFAULTS", "A dictionary in config.py with a safe value for every setting."), ("Override", "A value that replaces a lower layer's value."), ("Recursive merge", "Merging nested dictionaries key by key, not replacing whole sections."), (".env", "A private file of secrets that is never committed or put in restore points."), ("Wizard", "A guided setup that writes your first config.")],
 ["Order: DEFAULTS, then config.yaml, then dashboard overrides.", "Merging is recursive, so partial sections are fine.", "Secrets only in .env: VECTOR_NSEC and API keys.", "vectiq --check validates; --setup runs the wizard.", "Dashboard changes are saved in the database, not in your file."],
 [T("Think of paint layers. The bottom coat is the factory default. You paint your colours over it with config.yaml. Then a friend touches up a few spots with a small brush, the dashboard. What you see is the top-most paint in each spot."),
  F("4-1", "The top row wins. Secrets are kept apart in .env."),
  C("economy:\n  daily_amount: 300     # only this changes\n  work_cooldown_minutes: 30\nmoderation:\n  warn_threshold: 3\n  warn_action: timeout", "yaml"),
  T("Some defaults you will meet: the prefix is an exclamation mark; leveling gives 15 to 25 XP with a 60 second cooldown; economy pays 200 coins a day with a 25 coin streak bonus; three warnings trigger a timeout; scheduled restore points run every 24 hours and keep 14."),
  TB("A few defaults", ["Section", "Setting", "Default"], [["leveling", "xp_min / xp_max", "15 / 25"], ["leveling", "cooldown_seconds", "60"], ["economy", "daily_amount", "200"], ["economy", "start_balance", "100"], ["moderation", "warn_threshold", "3"], ["backup", "every_hours", "24"], ["games", "winner_coins", "50"]]),
  F("4-2", "A recursive merge changes only the keys you wrote."),
  TB("Where things live", ["What", "Where", "Why there"], [["bot key and API secrets", ".env", "never shared or backed up"], ["your normal settings", "config.yaml", "easy to read and review"], ["quick tweaks", "dashboard (database)", "no restart"], ["built-in values", "DEFAULTS in config.py", "safe fallback"]]),
  T("When Vectiq upgrades, old dashboard keys may need to move; a helper called upgrade_overrides migrates them at start-up so saved changes keep working.")],
 [("Which layer wins?", ["Dashboard overrides", "DEFAULTS", "config.yaml", "none"], 0, "They sit on top."), ("Where do secrets go?", [".env", "config.yaml", "the dashboard", "the README"], 0, "Never in the YAML."), ("What does recursive merge mean?", ["Nested keys merge individually", "Whole sections replace", "Files concatenate", "Keys are sorted"], 0, "Only written keys change."), ("Which flag validates the config?", ["--check", "--run", "--wipe", "--lint-db"], 0, "It checks without starting."), ("Where are dashboard changes saved?", ["In the database", "In config.yaml", "In .env", "Nowhere"], 0, "Layered over the file.")],
 [("What is DEFAULTS for?", "A safe value for every setting."), ("Why keep secrets in .env?", "So they are not in config or restore points."), ("What order are layers merged?", "Defaults, config.yaml, dashboard overrides."), ("What does --setup do?", "Runs the setup wizard.")],
 [MATCH("Match location to content", "Pair each place with what it holds.", [(".env", "bot key"), ("config.yaml", "your settings"), ("dashboard", "quick overrides"), ("DEFAULTS", "built-in values")]),
  FILL("Layers", "Settings start from {{DEFAULTS}}, are merged with {{config.yaml}}, and then {{dashboard}} overrides win.", ),
  PL("Merge two settings dicts", "Write merge(base, over). Return a new dict that has all keys of base, with values from over winning. When both values are dicts, merge them recursively. Do not change the inputs.", "merge(base, over)", '''
def merge(base, over):
    out = dict(base)
    for k, v in over.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = merge(out[k], v)
        else:
            out[k] = v
    return out
''', [[{"a": 1}, {"a": 2}], [{"e": {"d": 200}}, {"e": {"d": 300}}], [{"a": {"b": 1}}, {"a": {"b": 2}}], [{}, {"x": {"y": 1}}], [{"a": {"b": 1}}, {"a": 5}], [{"a": 1, "b": 2}, {}]], "Copy base, then for each key in over: if both sides are dicts, recurse; otherwise take over's value.")]))

