 [("Module", "A frozen dataclass describing one switchable feature."), ("Slot", "A role such as automod that only one enabled module may hold."), ("Plugin", "A module added from outside the project."), ("Entry point", "A pip mechanism that lets a package announce itself, here under vectiq.modules."), ("module_problems", "A record of why a module could not load: missing import, load error or slot conflict.")],
