 [("Why are plugins off by default?", "So untrusted code never runs unexpectedly."), ("Which two modules share the automod slot?", "sentire and sentire_official."), ("What is API_VERSION?", "The stable plugin API version, currently 1."), ("What records load problems?", "module_problems.")],
